IDS = ["DT-001","DT-002","DT-003","DT-004","DT-005","DT-006","DT-007","LR-001",
"LR2-013","LR2-014","LR2-015","LR2-016","LR2-017","LR2-018","LR2-019","LR2-020",
"LR2-021","LR2-022","LR2-023","LR2-024",
"LR3-002","LR3-004","LR3-006","LR3-008","LR3-010","LR3-101","LR3-104","LR3-107",
"LR3-110","LR3-112","LR3-114","LR3-116",
"LY-001","LY-002","LY-003","LY-004","LY-005","LY-006","LY-007","LY-008"]
assert len(IDS) == 40, len(IDS)
assert set(IDS) == set(P.keys()), (set(IDS) ^ set(P.keys()))
LIUYAO = {"DT-001","DT-002","DT-003","DT-004","DT-005","DT-006","DT-007",
"LY-001","LY-002","LY-003","LY-004","LY-005","LY-006","LY-007","LY-008"}
written = 0
cnt = {"changed_main":0, "reserve_used":0, "disputed":0}
for cid in IDS:
    d = P[cid]
    cm, ru, di, reason = d["trig"]
    if cid in LIUYAO:
        cnt["changed_main"] += bool(cm); cnt["reserve_used"] += bool(ru); cnt["disputed"] += bool(di)
    else:
        assert (cm, ru, di, reason) == (False, False, False, ""), cid
    rec = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
           "confidence": d["conf"],
           "trigger": {"changed_main": cm, "reserve_used": ru, "disputed": di, "reason": reason}}
    (OUT / f"{cid}.json").write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding="utf-8")
    written += 1
assert written == 40
# verify round-trip
for cid in IDS:
    r = json.loads((OUT / f"{cid}.json").read_text(encoding="utf-8"))
    assert r["case_id"] == cid and r["prediction_text"] and r["basis"] and 0 <= r["confidence"] <= 1
    assert set(r["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}
print("CASES", len(IDS), "WRITTEN", written, "LIUYAO_TRIGGER_COUNTS", cnt)
